apex_missing = False
try:
    from apex.normalization.fused_layer_norm import FusedRMSNorm
except ImportError:
    apex_missing = True

def pytest_configure(config):
    if apex_missing:
        config.addinivalue_line(
            "markers", "requires_apex: mark test as requiring apex module"
        )

def pytest_collection_modifyitems(items):
    """Skip tests that require apex if apex is not available."""
    skip_apex = pytest.mark.skip(reason="apex module not available (requires compilation)")
    for item in items:
        if apex_missing and ("test_rms_norm" in str(item.fspath)):
            item.add_marker(skip_apex)
